import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';  // Para capturar os IDs de cliente e projeto da URL

const AtividadeList = () => {
  const [atividades, setAtividades] = useState([]);
  const { clienteId, projetoId } = useParams(); // Pega o clienteId e projetoId da URL

  useEffect(() => {
    // Requisição para buscar as atividades de um projeto de um cliente específico
    axios.get(`http://localhost:8080/clientes/${clienteId}/projetos/${projetoId}/atividades`)
      .then(response => {
        setAtividades(response.data);
      })
      .catch(error => {
        console.error('Erro ao buscar atividades:', error);
      });
  }, [clienteId, projetoId]);

  return (
    <div className="atividade-list">
      <h2>Atividades do Projeto</h2>
      <ul>
        {atividades.map(atividade => (
          <li key={atividade.id}>{atividade.nome}</li>
        ))}
      </ul>
    </div>
  );
};

export default AtividadeList;
